PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL, email TEXT NOT NULL, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, date_of_birth TEXT NOT NULL, gender TEXT NOT NULL, location TEXT, status TEXT NOT NULL DEFAULT 'active', email_verified INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS users_username_unique ON users(username);
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique ON users(email);
CREATE INDEX IF NOT EXISTS users_status_idx ON users(status);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, bio TEXT, avatar_url TEXT, cover_url TEXT, city TEXT, country TEXT, occupation TEXT, education TEXT, height_cm INTEGER, intentions TEXT, relationship_status TEXT, show_age INTEGER NOT NULL DEFAULT 1, is_private INTEGER NOT NULL DEFAULT 0, profile_completion INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS profiles_user_unique ON profiles(user_id);
CREATE TABLE IF NOT EXISTS user_preferences (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, min_age INTEGER NOT NULL DEFAULT 18, max_age INTEGER NOT NULL DEFAULT 99, preferred_genders TEXT NOT NULL DEFAULT '[]', max_distance_km INTEGER, intentions TEXT, show_me INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS user_preferences_user_unique ON user_preferences(user_id);
CREATE TABLE IF NOT EXISTS interests (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL, category TEXT, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS interests_name_unique ON interests(name);
CREATE UNIQUE INDEX IF NOT EXISTS interests_slug_unique ON interests(slug);
CREATE TABLE IF NOT EXISTS user_interests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, interest_id TEXT NOT NULL REFERENCES interests(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS user_interests_pair_unique ON user_interests(user_id, interest_id);
CREATE INDEX IF NOT EXISTS user_interests_user_idx ON user_interests(user_id);
CREATE TABLE IF NOT EXISTS likes (id TEXT PRIMARY KEY, liker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, liked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL DEFAULT 'like', created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS likes_pair_unique ON likes(liker_id, liked_id);
CREATE INDEX IF NOT EXISTS likes_liked_idx ON likes(liked_id);
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY, user_a_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_b_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, unmatched_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS matches_pair_unique ON matches(user_a_id, user_b_id);
CREATE INDEX IF NOT EXISTS matches_user_a_idx ON matches(user_a_id);
CREATE INDEX IF NOT EXISTS matches_user_b_idx ON matches(user_b_id);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, match_id TEXT REFERENCES matches(id) ON DELETE SET NULL, type TEXT NOT NULL DEFAULT 'direct', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS conversations_match_unique ON conversations(match_id);
CREATE TABLE IF NOT EXISTS conversation_members (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, last_read_at INTEGER, joined_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS conversation_members_pair_unique ON conversation_members(conversation_id, user_id);
CREATE INDEX IF NOT EXISTS conversation_members_user_idx ON conversation_members(user_id);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'text', created_at INTEGER NOT NULL, read_at INTEGER, edited_at INTEGER);
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id, created_at);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, image_url TEXT, feeling TEXT, location TEXT, hashtags TEXT NOT NULL DEFAULT '[]', visibility TEXT NOT NULL DEFAULT 'public', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS posts_author_idx ON posts(author_id);
CREATE INDEX IF NOT EXISTS posts_created_idx ON posts(created_at);
CREATE TABLE IF NOT EXISTS post_likes (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS post_likes_pair_unique ON post_likes(post_id, user_id);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, confession_id TEXT REFERENCES confessions(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS comments_post_idx ON comments(post_id);
CREATE INDEX IF NOT EXISTS comments_confession_idx ON comments(confession_id);
CREATE TABLE IF NOT EXISTS follows (id TEXT PRIMARY KEY, follower_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, following_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS follows_pair_unique ON follows(follower_id, following_id);
CREATE INDEX IF NOT EXISTS follows_following_idx ON follows(following_id);
CREATE TABLE IF NOT EXISTS confessions (id TEXT PRIMARY KEY, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, is_anonymous INTEGER NOT NULL DEFAULT 1, body TEXT NOT NULL, category TEXT, mood TEXT, hashtags TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'published', created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS confessions_created_idx ON confessions(created_at);
CREATE INDEX IF NOT EXISTS confessions_status_idx ON confessions(status);
CREATE TABLE IF NOT EXISTS confession_likes (id TEXT PRIMARY KEY, confession_id TEXT NOT NULL REFERENCES confessions(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS confession_likes_pair_unique ON confession_likes(confession_id, user_id);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, data TEXT, related_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id, created_at);
CREATE INDEX IF NOT EXISTS notifications_unread_idx ON notifications(user_id, is_read);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_type TEXT NOT NULL, target_id TEXT NOT NULL, reason TEXT NOT NULL, details TEXT, status TEXT NOT NULL DEFAULT 'open', reviewed_by TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reports_status_idx ON reports(status);
CREATE INDEX IF NOT EXISTS reports_target_idx ON reports(target_type, target_id);
CREATE TABLE IF NOT EXISTS blocks (id TEXT PRIMARY KEY, blocker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS blocks_pair_unique ON blocks(blocker_id, blocked_id);
CREATE TABLE IF NOT EXISTS saved_posts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, confession_id TEXT REFERENCES confessions(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS saved_posts_post_unique ON saved_posts(user_id, post_id);
CREATE UNIQUE INDEX IF NOT EXISTS saved_posts_confession_unique ON saved_posts(user_id, confession_id);
CREATE TABLE IF NOT EXISTS email_verifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS email_verifications_token_unique ON email_verifications(token_hash);
CREATE TABLE IF NOT EXISTS password_resets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS password_resets_token_unique ON password_resets(token_hash);
CREATE TABLE IF NOT EXISTS admin_users (id TEXT PRIMARY KEY, email TEXT NOT NULL, password_hash TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at INTEGER NOT NULL, last_login_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS admin_users_email_unique ON admin_users(email);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, admin_id TEXT REFERENCES admin_users(id) ON DELETE SET NULL, action TEXT NOT NULL, target_type TEXT, target_id TEXT, details TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS audit_logs_admin_idx ON audit_logs(admin_id);
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON audit_logs(created_at);
CREATE TABLE IF NOT EXISTS platform_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL);
